"""Patch the vendored occt-import-js glue so embind builds its call wrappers as closures, not with Function().

The published build generates each wrapper's source as a string and evaluates it (Emscripten's default,
DYNAMIC_EXECUTION=1), which a content policy without 'unsafe-eval' blocks. The replacement performs the same
steps the generated source does; see createJsInvoker in the same file for that source. The .wasm is untouched.

Usage: python apply_local_patch.py PUBLISHED_occt-import-js.js OUT.js   (occt-import-js 0.0.23)
"""
import pathlib
import sys

SRC, DST = pathlib.Path(sys.argv[1]), pathlib.Path(sys.argv[2])  # the published dist/occt-import-js.js, and where to write

s = SRC.read_bytes().decode("utf-8")
old = ('var closureArgs=[humanName,throwBindingError,cppInvokerFunc,cppTargetFunc,runDestructors,argTypes[0],argTypes[1]];'
       'for(var i=0;i<argCount-2;++i){closureArgs.push(argTypes[i+2])}'
       'if(!needsDestructorStack){for(var i=isClassMethodFunc?1:2;i<argTypes.length;++i){'
       'if(argTypes[i].destructorFunction!==null){closureArgs.push(argTypes[i].destructorFunction)}}}'
       'let[args,invokerFnBody]=createJsInvoker(argTypes,isClassMethodFunc,returns,isAsync);args.push(invokerFnBody);'
       'var invokerFn=newFunc(Function,args)(...closureArgs);')
new = ('/* Local patch (Acoustic Phase Optimizer, 2026-11-11): the wrapper is a closure doing what the source '
       'generated by createJsInvoker does, instead of that source being evaluated with Function(), so the '
       'library runs under a Content-Security-Policy without unsafe-eval. */'
       'var expectedArgCount=argCount-2;'
       'var invokerFn=function(...args){'
       'var destructors=needsDestructorStack?[]:null;'
       'var wired=new Array(expectedArgCount);'
       'var callArgs=[cppTargetFunc];'
       'var thisWired;'
       'if(isClassMethodFunc){thisWired=argTypes[1]["toWireType"](destructors,this);callArgs.push(thisWired)}'
       'for(var i=0;i<expectedArgCount;++i){wired[i]=argTypes[i+2]["toWireType"](destructors,args[i]);callArgs.push(wired[i])}'
       'var rv=cppInvokerFunc(...callArgs);'
       'if(needsDestructorStack){runDestructors(destructors)}'
       'else{for(var j=isClassMethodFunc?1:2;j<argTypes.length;++j){var param=j===1?thisWired:wired[j-2];'
       'if(argTypes[j].destructorFunction!==null){argTypes[j].destructorFunction(param)}}}'
       'if(returns){return argTypes[0]["fromWireType"](rv)}'
       '};')
assert s.count(old) == 1, s.count(old)
s = s.replace(old, new)

# The second place: emval method callers (C++ calling JavaScript functions, methods and constructors).
start = s.index('var functionBody=`return function (obj, func, destructorsRef, args) {')
end_marker = 'var invokerFunction=newFunc(Function,params)(...args);'
end = s.index(end_marker, start) + len(end_marker)
generated = s[start:end]
# what is being replaced must be exactly the code this translation was written against
assert generated.count('functionBody+=') == 4 and 'kind===1?"new func":"func.call"' in generated and 'if(kind===0){argsList.push("obj")}' in generated, generated
caller = ('/* Local patch (Acoustic Phase Optimizer, 2026-11-11): a closure in place of source evaluated with '
          'Function(); see the note in craftInvokerFunction. */'
          'var invokerFunction=function(obj,func,destructorsRef,args){'
          'var offset=0;'
          'var list=kind===0?[obj]:[];'
          'for(var i=0;i<argCount;++i){list.push(types[i].readValueFromPointer(args+offset));offset+=types[i].argPackAdvance}'
          'var rv=kind===1?Reflect.construct(func,list):func.call(...list);'
          'if(!retType.isVoid){return emval_returnValue(retType,destructorsRef,rv)}'
          '};')
s = s[:start] + caller + s[end:]
assert "newFunc(Function" not in s
DST.write_bytes(s.encode("utf-8"))
print("patched", len(s))
